"""
Embedded Mobile Games for RAMAZAN AI Web Dashboard.
Preserves mobile interactive demos without polluting repository root with untracked HTML artifacts.
"""

MONKEY_GAME_HTML = '<!DOCTYPE html>\n<html lang="tr">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">\n  <title>Zıplayan Maymun (Jumping Monkey) - RAMAZAN AI</title>\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; -webkit-user-select: none; }\n    body {\n      background: #0f172a;\n      color: #fff;\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      min-height: 100vh;\n      min-height: 100dvh;\n      overflow: hidden;\n    }\n    #game-wrapper {\n      position: relative;\n      width: 100%;\n      max-width: 440px;\n      height: 100vh;\n      height: 100dvh;\n      background: linear-gradient(180deg, #1e3a5f 0%, #14532d 100%);\n      box-shadow: 0 0 30px rgba(0,0,0,0.8);\n      overflow: hidden;\n    }\n    #gameCanvas {\n      display: block;\n      width: 100%;\n      height: 100%;\n    }\n    /* Touch Controls Overlay */\n    .touch-controls {\n      position: absolute;\n      bottom: 1.5rem;\n      left: 0;\n      right: 0;\n      display: flex;\n      justify-content: space-between;\n      padding: 0 1.5rem;\n      pointer-events: none;\n      z-index: 10;\n    }\n    .touch-btn {\n      pointer-events: auto;\n      width: 68px;\n      height: 68px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.18);\n      backdrop-filter: blur(8px);\n      border: 2px solid rgba(255, 255, 255, 0.35);\n      color: #fff;\n      font-size: 1.6rem;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 4px 15px rgba(0,0,0,0.4);\n    }\n    .touch-btn:active {\n      background: rgba(16, 185, 129, 0.5);\n      transform: scale(0.92);\n    }\n    .hud {\n      position: absolute;\n      top: 1rem;\n      left: 1rem;\n      right: 1rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      font-weight: 800;\n      font-size: 1rem;\n      text-shadow: 0 2px 4px rgba(0,0,0,0.6);\n      z-index: 10;\n    }\n    .hud-badge {\n      background: rgba(0,0,0,0.45);\n      backdrop-filter: blur(4px);\n      padding: 0.35rem 0.8rem;\n      border-radius: 20px;\n      border: 1px solid rgba(255,255,255,0.15);\n      display: flex;\n      align-items: center;\n      gap: 0.3rem;\n    }\n    /* Game Over / Start Overlay */\n    .overlay-screen {\n      position: absolute;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background: rgba(15, 23, 42, 0.85);\n      backdrop-filter: blur(6px);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      gap: 1.2rem;\n      padding: 2rem;\n      text-align: center;\n      z-index: 20;\n    }\n    .overlay-screen h1 {\n      font-size: 2rem;\n      font-weight: 900;\n      color: #fbbf24;\n      text-shadow: 0 3px 10px rgba(251, 191, 36, 0.4);\n    }\n    .play-btn {\n      background: linear-gradient(135deg, #10b981, #059669);\n      border: none;\n      color: #fff;\n      padding: 0.85rem 2.2rem;\n      border-radius: 30px;\n      font-size: 1.15rem;\n      font-weight: 800;\n      cursor: pointer;\n      box-shadow: 0 4px 20px rgba(16, 185, 129, 0.5);\n      transition: transform 0.1s ease;\n    }\n    .play-btn:active { transform: scale(0.95); }\n  </style>\n</head>\n<body>\n\n  <div id="game-wrapper">\n    <!-- Heads-Up Display -->\n    <div class="hud">\n      <div class="hud-badge">🍌 <span id="scoreVal">0</span></div>\n      <div class="hud-badge">🏆 En Yüksek: <span id="highScoreVal">0</span></div>\n    </div>\n\n    <!-- Main Game Canvas -->\n    <canvas id="gameCanvas"></canvas>\n\n    <!-- Touch Navigation for Mobile -->\n    <div class="touch-controls">\n      <div class="touch-btn" id="btnLeft">◀</div>\n      <div class="touch-btn" id="btnRight">▶</div>\n    </div>\n\n    <!-- Start / Game Over Modal -->\n    <div class="overlay-screen" id="overlay">\n      <div style="font-size: 4rem;">🐵</div>\n      <h1 id="overlayTitle">Zıplayan Maymun</h1>\n      <p id="overlayDesc" style="color: #cbd5e1; font-size: 0.95rem; line-height: 1.4;">\n        Platformlardan zıplayarak yukarı tırman, muzları topla ve aşağı düşme!\n      </p>\n      <button class="play-btn" id="playBtn" onclick="startGame()">OYNA</button>\n    </div>\n  </div>\n\n  <script>\n    const canvas = document.getElementById(\'gameCanvas\');\n    const ctx = canvas.getContext(\'2d\');\n    const wrapper = document.getElementById(\'game-wrapper\');\n\n    let width, height;\n    function resizeCanvas() {\n      width = wrapper.clientWidth;\n      height = wrapper.clientHeight;\n      canvas.width = width;\n      canvas.height = height;\n    }\n    window.addEventListener(\'resize\', resizeCanvas);\n    resizeCanvas();\n\n    // Game Variables\n    let gameState = "START"; // START, PLAYING, GAMEOVER\n    let score = 0;\n    let highScore = localStorage.getItem(\'monkey_high_score\') || 0;\n    document.getElementById(\'highScoreVal\').innerText = highScore;\n\n    // Monkey Character\n    const monkey = {\n      x: width / 2 - 20,\n      y: height - 120,\n      w: 36,\n      h: 42,\n      vx: 0,\n      vy: -12,\n      speed: 6.5,\n      gravity: 0.38,\n      jumpStrength: -11.5,\n      facingRight: true\n    };\n\n    // Platforms & Bananas\n    let platforms = [];\n    let bananas = [];\n    const PLATFORM_COUNT = 7;\n\n    function initPlatforms() {\n      platforms = [];\n      bananas = [];\n      // Starting base platform\n      platforms.push({ x: width / 2 - 50, y: height - 40, w: 100, h: 14, type: \'normal\' });\n\n      for (let i = 1; i < PLATFORM_COUNT; i++) {\n        const py = height - (i * (height / PLATFORM_COUNT));\n        const px = Math.random() * (width - 80);\n        const pType = Math.random() < 0.2 ? \'spring\' : \'normal\';\n        platforms.push({ x: px, y: py, w: 75, h: 14, type: pType });\n\n        // Spawn banana occasionally\n        if (Math.random() < 0.45) {\n          bananas.push({ x: px + 28, y: py - 26, w: 18, h: 18, collected: false });\n        }\n      }\n    }\n\n    // Input handlers\n    const keys = { left: false, right: false };\n\n    window.addEventListener(\'keydown\', e => {\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = true;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = true;\n    });\n    window.addEventListener(\'keyup\', e => {\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = false;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = false;\n    });\n\n    // Touch Controls\n    const btnLeft = document.getElementById(\'btnLeft\');\n    const btnRight = document.getElementById(\'btnRight\');\n\n    btnLeft.addEventListener(\'touchstart\', e => { e.preventDefault(); keys.left = true; });\n    btnLeft.addEventListener(\'touchend\', e => { e.preventDefault(); keys.left = false; });\n    btnRight.addEventListener(\'touchstart\', e => { e.preventDefault(); keys.right = true; });\n    btnRight.addEventListener(\'touchend\', e => { e.preventDefault(); keys.right = false; });\n\n    // Touch / Tilt fallback: tap canvas on left/right half\n    canvas.addEventListener(\'touchstart\', e => {\n      const touchX = e.touches[0].clientX - wrapper.getBoundingClientRect().left;\n      if (touchX < width / 2) keys.left = true;\n      else keys.right = true;\n    });\n    canvas.addEventListener(\'touchend\', () => {\n      keys.left = false;\n      keys.right = false;\n    });\n\n    function startGame() {\n      document.getElementById(\'overlay\').style.display = \'none\';\n      score = 0;\n      document.getElementById(\'scoreVal\').innerText = score;\n      monkey.x = width / 2 - 18;\n      monkey.y = height - 120;\n      monkey.vx = 0;\n      monkey.vy = -12;\n      initPlatforms();\n      gameState = "PLAYING";\n    }\n\n    function gameOver() {\n      gameState = "GAMEOVER";\n      if (score > highScore) {\n        highScore = score;\n        localStorage.setItem(\'monkey_high_score\', highScore);\n        document.getElementById(\'highScoreVal\').innerText = highScore;\n      }\n      document.getElementById(\'overlayTitle\').innerText = "Oyun Bitti!";\n      document.getElementById(\'overlayDesc\').innerHTML = `Maymun düştü! 🍌 <strong>Skorun: ${score}</strong><br>En Yüksek Skor: ${highScore}`;\n      document.getElementById(\'playBtn\').innerText = "TEKRAR DENE";\n      document.getElementById(\'overlay\').style.display = \'flex\';\n    }\n\n    // Main Game Loop\n    function update() {\n      if (gameState !== "PLAYING") return;\n\n      // Horizontal movement\n      if (keys.left) {\n        monkey.vx = -monkey.speed;\n        monkey.facingRight = false;\n      } else if (keys.right) {\n        monkey.vx = monkey.speed;\n        monkey.facingRight = true;\n      } else {\n        monkey.vx *= 0.82;\n      }\n\n      monkey.x += monkey.vx;\n      // Screen wrap\n      if (monkey.x < -monkey.w) monkey.x = width;\n      if (monkey.x > width) monkey.x = -monkey.w;\n\n      // Vertical movement & gravity\n      monkey.vy += monkey.gravity;\n      monkey.y += monkey.vy;\n\n      // Camera scroll when monkey climbs above mid screen\n      if (monkey.y < height * 0.42 && monkey.vy < 0) {\n        const diff = (height * 0.42) - monkey.y;\n        monkey.y = height * 0.42;\n        score += Math.floor(diff / 5);\n        document.getElementById(\'scoreVal\').innerText = score;\n\n        // Shift platforms and bananas down\n        platforms.forEach(p => {\n          p.y += diff;\n          if (p.y > height) {\n            p.y = 0;\n            p.x = Math.random() * (width - 75);\n            p.type = Math.random() < 0.2 ? \'spring\' : \'normal\';\n          }\n        });\n\n        bananas.forEach(b => {\n          b.y += diff;\n          if (b.y > height) {\n            b.y = -30;\n            b.x = Math.random() * (width - 30);\n            b.collected = false;\n          }\n        });\n      }\n\n      // Platform Collisions (only when falling)\n      if (monkey.vy > 0) {\n        platforms.forEach(p => {\n          if (\n            monkey.x + monkey.w * 0.7 > p.x &&\n            monkey.x + monkey.w * 0.3 < p.x + p.w &&\n            monkey.y + monkey.h >= p.y &&\n            monkey.y + monkey.h <= p.y + p.h + 10\n          ) {\n            if (p.type === \'spring\') {\n              monkey.vy = monkey.jumpStrength * 1.5; // Super jump!\n            } else {\n              monkey.vy = monkey.jumpStrength;\n            }\n          }\n        });\n      }\n\n      // Banana Collection\n      bananas.forEach(b => {\n        if (!b.collected &&\n            monkey.x < b.x + b.w &&\n            monkey.x + monkey.w > b.x &&\n            monkey.y < b.y + b.h &&\n            monkey.y + monkey.h > b.y) {\n          b.collected = true;\n          score += 50;\n          document.getElementById(\'scoreVal\').innerText = score;\n        }\n      });\n\n      // Bottom death check\n      if (monkey.y > height) {\n        gameOver();\n      }\n    }\n\n    function render() {\n      ctx.clearRect(0, 0, width, height);\n\n      // Draw Platforms\n      platforms.forEach(p => {\n        if (p.type === \'spring\') {\n          ctx.fillStyle = \'#f59e0b\'; // Amber spring platform\n        } else {\n          ctx.fillStyle = \'#10b981\'; // Emerald vine platform\n        }\n        ctx.beginPath();\n        ctx.roundRect(p.x, p.y, p.w, p.h, 6);\n        ctx.fill();\n\n        // Platform top highlight\n        ctx.fillStyle = p.type === \'spring\' ? \'#fde68a\' : \'#6ee7b7\';\n        ctx.fillRect(p.x + 4, p.y + 2, p.w - 8, 3);\n      });\n\n      // Draw Bananas\n      bananas.forEach(b => {\n        if (!b.collected) {\n          ctx.font = "20px sans-serif";\n          ctx.fillText("🍌", b.x, b.y + 16);\n        }\n      });\n\n      // Draw Monkey\n      ctx.save();\n      ctx.translate(monkey.x + monkey.w / 2, monkey.y + monkey.h / 2);\n      if (!monkey.facingRight) ctx.scale(-1, 1);\n      ctx.font = "34px sans-serif";\n      ctx.textAlign = "center";\n      ctx.textBaseline = "middle";\n      ctx.fillText("🐒", 0, 0);\n      ctx.restore();\n    }\n\n    function loop() {\n      update();\n      render();\n      requestAnimationFrame(loop);\n    }\n    initPlatforms();\n    requestAnimationFrame(loop);\n  </script>\n</body>\n</html>\n'

COPS_ROBBERS_GAME_HTML = '<!DOCTYPE html>\n<html lang="tr">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">\n  <title>Hırsız Polis Kovalamacası - RAMAZAN AI</title>\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; -webkit-user-select: none; }\n    body {\n      background: #020617;\n      color: #fff;\n      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      min-height: 100vh;\n      min-height: 100dvh;\n      overflow: hidden;\n    }\n    #game-container {\n      position: relative;\n      width: 100%;\n      max-width: 440px;\n      height: 100vh;\n      height: 100dvh;\n      background: #0b0f19;\n      box-shadow: 0 0 35px rgba(0,0,0,0.9);\n      overflow: hidden;\n    }\n    #gameCanvas {\n      display: block;\n      width: 100%;\n      height: 100%;\n    }\n    /* Top HUD */\n    .top-hud {\n      position: absolute;\n      top: 0.8rem;\n      left: 0.8rem;\n      right: 0.8rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      z-index: 10;\n      pointer-events: none;\n    }\n    .hud-chip {\n      background: rgba(15, 23, 42, 0.75);\n      backdrop-filter: blur(8px);\n      padding: 0.4rem 0.75rem;\n      border-radius: 20px;\n      border: 1px solid rgba(255, 255, 255, 0.15);\n      font-size: 0.85rem;\n      font-weight: 800;\n      display: flex;\n      align-items: center;\n      gap: 0.35rem;\n    }\n    .wanted-stars {\n      color: #f59e0b;\n      letter-spacing: 2px;\n    }\n    /* Mobile D-Pad & Action Buttons */\n    .mobile-controls {\n      position: absolute;\n      bottom: 1.2rem;\n      left: 1rem;\n      right: 1rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-end;\n      z-index: 10;\n      pointer-events: none;\n    }\n    .dpad {\n      pointer-events: auto;\n      display: grid;\n      grid-template-columns: repeat(3, 52px);\n      grid-template-rows: repeat(3, 52px);\n      gap: 4px;\n    }\n    .d-btn {\n      background: rgba(30, 41, 59, 0.85);\n      backdrop-filter: blur(6px);\n      border: 1.5px solid rgba(255, 255, 255, 0.25);\n      border-radius: 12px;\n      color: #fff;\n      font-size: 1.25rem;\n      font-weight: 800;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n    .d-btn:active {\n      background: rgba(59, 130, 246, 0.6);\n      transform: scale(0.92);\n    }\n    .boost-btn {\n      pointer-events: auto;\n      width: 70px;\n      height: 70px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #f59e0b, #d97706);\n      border: 2px solid rgba(255, 255, 255, 0.4);\n      color: #fff;\n      font-size: 1.5rem;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 4px 18px rgba(245, 158, 11, 0.5);\n    }\n    .boost-btn:active {\n      transform: scale(0.92);\n      filter: brightness(1.2);\n    }\n    /* Modal Screen */\n    .screen-modal {\n      position: absolute;\n      top: 0; left: 0; right: 0; bottom: 0;\n      background: rgba(11, 15, 25, 0.92);\n      backdrop-filter: blur(8px);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      gap: 1.1rem;\n      padding: 2rem;\n      text-align: center;\n      z-index: 20;\n    }\n    .screen-modal h1 {\n      font-size: 2.1rem;\n      font-weight: 900;\n      color: #ef4444;\n      text-shadow: 0 0 20px rgba(239, 68, 68, 0.5);\n    }\n    .start-btn {\n      background: linear-gradient(135deg, #ef4444, #dc2626);\n      border: none;\n      color: #fff;\n      padding: 0.85rem 2.4rem;\n      border-radius: 30px;\n      font-size: 1.15rem;\n      font-weight: 800;\n      cursor: pointer;\n      box-shadow: 0 4px 20px rgba(239, 68, 68, 0.6);\n    }\n    .start-btn:active { transform: scale(0.95); }\n  </style>\n</head>\n<body>\n\n  <div id="game-container">\n    <!-- Top HUD -->\n    <div class="top-hud">\n      <div class="hud-chip">💰 <span id="scoreText">0</span></div>\n      <div class="hud-chip"><span class="wanted-stars" id="starsText">★☆☆☆☆</span></div>\n      <div class="hud-chip" id="livesText">❤️❤️❤️</div>\n    </div>\n\n    <!-- Main Canvas -->\n    <canvas id="gameCanvas"></canvas>\n\n    <!-- Controls for Mobile Touch -->\n    <div class="mobile-controls">\n      <div class="dpad">\n        <div></div>\n        <div class="d-btn" id="btnUp">▲</div>\n        <div></div>\n        <div class="d-btn" id="btnLeft">◀</div>\n        <div></div>\n        <div class="d-btn" id="btnRight">▶</div>\n        <div></div>\n        <div class="d-btn" id="btnDown">▼</div>\n        <div></div>\n      </div>\n\n      <div class="boost-btn" id="btnBoost">\n        <span>⚡</span>\n        <span style="font-size: 0.65rem; font-weight: 800;">HIZ</span>\n      </div>\n    </div>\n\n    <!-- Start / End Screen -->\n    <div class="screen-modal" id="gameModal">\n      <div style="font-size: 4rem;">🚨 🏃💨 🚓</div>\n      <h1 id="modalTitle">HIRSIZ POLİS</h1>\n      <p id="modalDesc" style="color: #cbd5e1; font-size: 0.95rem; line-height: 1.45;">\n        Paraları topla, peşindeki polis arabalarından kaç!<br>\n        Sıkıştığında ⚡ HIZ butonuna basarak hızlan.\n      </p>\n      <button class="start-btn" id="modalBtn" onclick="startGame()">KAÇIŞI BAŞLAT</button>\n    </div>\n  </div>\n\n  <script>\n    const canvas = document.getElementById(\'gameCanvas\');\n    const ctx = canvas.getContext(\'2d\');\n    const container = document.getElementById(\'game-container\');\n\n    let W, H;\n    function resize() {\n      W = container.clientWidth;\n      H = container.clientHeight;\n      canvas.width = W;\n      canvas.height = H;\n    }\n    window.addEventListener(\'resize\', resize);\n    resize();\n\n    // Sound synthesizer using Web Audio API (Zero external audio files)\n    const AudioCtx = window.AudioContext || window.webkitAudioContext;\n    let audioCtx = null;\n    function playBeep(freq, duration, type="sine") {\n      try {\n        if (!audioCtx) audioCtx = new AudioCtx();\n        const osc = audioCtx.createOscillator();\n        const gain = audioCtx.createGain();\n        osc.type = type;\n        osc.frequency.value = freq;\n        osc.connect(gain);\n        gain.connect(audioCtx.destination);\n        gain.gain.setValueAtTime(0.12, audioCtx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);\n        osc.start();\n        osc.stop(audioCtx.currentTime + duration);\n      } catch (e) {}\n    }\n\n    // Game Variables\n    let gameState = "MENU"; // MENU, PLAYING, GAMEOVER\n    let score = 0;\n    let lives = 3;\n    let wantedStars = 1;\n    let boostAvailable = 100;\n    let isBoosting = false;\n    let highScore = localStorage.getItem(\'cops_high_score\') || 0;\n\n    // Player (The Robber)\n    const player = {\n      x: W / 2,\n      y: H / 2,\n      size: 26,\n      baseSpeed: 3.8,\n      speed: 3.8,\n      dirX: 0,\n      dirY: 0\n    };\n\n    // Police Cars\n    let cops = [];\n    const copColors = [\'#3b82f6\', \'#ef4444\']; // Red & Blue sirens\n\n    // Money bags\n    let lootBags = [];\n\n    function spawnLoot() {\n      lootBags.push({\n        x: 30 + Math.random() * (W - 60),\n        y: 40 + Math.random() * (H - 220),\n        value: 100,\n        radius: 12\n      });\n    }\n\n    function spawnCop() {\n      const edge = Math.floor(Math.random() * 4);\n      let cx = 0, cy = 0;\n      if (edge === 0) { cx = Math.random() * W; cy = 20; }\n      else if (edge === 1) { cx = W - 20; cy = Math.random() * H; }\n      else if (edge === 2) { cx = Math.random() * W; cy = H - 180; }\n      else { cx = 20; cy = Math.random() * H; }\n\n      cops.push({\n        x: cx,\n        y: cy,\n        size: 28,\n        speed: 2.1 + (wantedStars * 0.35),\n        sirenFlash: 0\n      });\n    }\n\n    // Controls\n    const keys = { up: false, down: false, left: false, right: false, boost: false };\n\n    window.addEventListener(\'keydown\', e => {\n      if (e.code === \'ArrowUp\' || e.code === \'KeyW\') keys.up = true;\n      if (e.code === \'ArrowDown\' || e.code === \'KeyS\') keys.down = true;\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = true;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = true;\n      if (e.code === \'Space\') keys.boost = true;\n    });\n    window.addEventListener(\'keyup\', e => {\n      if (e.code === \'ArrowUp\' || e.code === \'KeyW\') keys.up = false;\n      if (e.code === \'ArrowDown\' || e.code === \'KeyS\') keys.down = false;\n      if (e.code === \'ArrowLeft\' || e.code === \'KeyA\') keys.left = false;\n      if (e.code === \'ArrowRight\' || e.code === \'KeyD\') keys.right = false;\n      if (e.code === \'Space\') keys.boost = false;\n    });\n\n    // Touch D-Pad Controls\n    function bindTouch(id, key) {\n      const el = document.getElementById(id);\n      el.addEventListener(\'touchstart\', e => { e.preventDefault(); keys[key] = true; });\n      el.addEventListener(\'touchend\', e => { e.preventDefault(); keys[key] = false; });\n    }\n    bindTouch(\'btnUp\', \'up\');\n    bindTouch(\'btnDown\', \'down\');\n    bindTouch(\'btnLeft\', \'left\');\n    bindTouch(\'btnRight\', \'right\');\n    bindTouch(\'btnBoost\', \'boost\');\n\n    function startGame() {\n      document.getElementById(\'gameModal\').style.display = \'none\';\n      score = 0;\n      lives = 3;\n      wantedStars = 1;\n      boostAvailable = 100;\n      player.x = W / 2;\n      player.y = H / 2;\n      cops = [];\n      lootBags = [];\n\n      for (let i = 0; i < 4; i++) spawnLoot();\n      spawnCop();\n      spawnCop();\n\n      updateHUD();\n      gameState = "PLAYING";\n      playBeep(440, 0.15, "triangle");\n    }\n\n    function updateHUD() {\n      document.getElementById(\'scoreText\').innerText = score;\n      let stars = "";\n      for (let i = 1; i <= 5; i++) stars += (i <= wantedStars ? "★" : "☆");\n      document.getElementById(\'starsText\').innerText = stars;\n      let hearts = "";\n      for (let i = 0; i < lives; i++) hearts += "❤️";\n      document.getElementById(\'livesText\').innerText = hearts;\n    }\n\n    function gameOver() {\n      gameState = "GAMEOVER";\n      playBeep(180, 0.5, "sawtooth");\n      if (score > highScore) {\n        highScore = score;\n        localStorage.setItem(\'cops_high_score\', highScore);\n      }\n      document.getElementById(\'modalTitle\').innerText = "YAKALANDIN!";\n      document.getElementById(\'modalDesc\').innerHTML = `Polisler seni kuşattı! 🚨<br><strong>Toplanan Ganimet: $${score}</strong><br>En Yüksek Skor: $${highScore}`;\n      document.getElementById(\'modalBtn\').innerText = "TEKRAR KAÇ";\n      document.getElementById(\'gameModal\').style.display = \'flex\';\n    }\n\n    // Game Update Loop\n    function update() {\n      if (gameState !== "PLAYING") return;\n\n      // Boost calculation\n      isBoosting = keys.boost && boostAvailable > 5;\n      if (isBoosting) {\n        player.speed = player.baseSpeed * 1.65;\n        boostAvailable = Math.max(0, boostAvailable - 1.2);\n      } else {\n        player.speed = player.baseSpeed;\n        boostAvailable = Math.min(100, boostAvailable + 0.35);\n      }\n\n      // Player Movement\n      let dx = 0, dy = 0;\n      if (keys.up) dy -= 1;\n      if (keys.down) dy += 1;\n      if (keys.left) dx -= 1;\n      if (keys.right) dx += 1;\n\n      // Normalize diagonal\n      if (dx !== 0 && dy !== 0) {\n        dx *= 0.7071;\n        dy *= 0.7071;\n      }\n\n      player.x += dx * player.speed;\n      player.y += dy * player.speed;\n\n      // Bounds check\n      const boundBottom = H - 180;\n      player.x = Math.max(16, Math.min(W - 16, player.x));\n      player.y = Math.max(45, Math.min(boundBottom, player.y));\n\n      // Loot Collection\n      lootBags.forEach((loot, idx) => {\n        const dist = Math.hypot(player.x - loot.x, player.y - loot.y);\n        if (dist < player.size / 2 + loot.radius) {\n          score += loot.value;\n          playBeep(880, 0.1, "sine");\n          lootBags.splice(idx, 1);\n          spawnLoot();\n\n          // Increase Wanted level every $400\n          const newStars = Math.min(5, Math.floor(score / 400) + 1);\n          if (newStars > wantedStars) {\n            wantedStars = newStars;\n            spawnCop();\n            playBeep(650, 0.3, "square");\n          }\n          updateHUD();\n        }\n      });\n\n      // Police Movement and AI Chasing\n      cops.forEach(cop => {\n        const angle = Math.atan2(player.y - cop.y, player.x - cop.x);\n        cop.x += Math.cos(angle) * cop.speed;\n        cop.y += Math.sin(angle) * cop.speed;\n        cop.sirenFlash += 0.2;\n\n        // Collision with player\n        const distToPlayer = Math.hypot(player.x - cop.x, player.y - cop.y);\n        if (distToPlayer < (player.size / 2 + cop.size / 2) - 4) {\n          lives -= 1;\n          playBeep(220, 0.3, "sawtooth");\n          updateHUD();\n\n          // Reposition cop after hit\n          cop.x = Math.random() < 0.5 ? 20 : W - 20;\n          cop.y = 30;\n\n          if (lives <= 0) {\n            gameOver();\n          }\n        }\n      });\n    }\n\n    // Render Canvas\n    function render() {\n      ctx.clearRect(0, 0, W, H);\n\n      // Grid City Streets\n      ctx.strokeStyle = \'#1e293b\';\n      ctx.lineWidth = 1;\n      for (let x = 0; x < W; x += 40) {\n        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, H); ctx.stroke();\n      }\n      for (let y = 0; y < H; y += 40) {\n        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();\n      }\n\n      // Boundary Barricade\n      ctx.strokeStyle = \'#ef4444\';\n      ctx.lineWidth = 2;\n      ctx.setLineDash([8, 8]);\n      ctx.beginPath();\n      ctx.moveTo(0, H - 175);\n      ctx.lineTo(W, H - 175);\n      ctx.stroke();\n      ctx.setLineDash([]);\n\n      // Draw Loot Bags\n      lootBags.forEach(loot => {\n        ctx.font = "20px sans-serif";\n        ctx.textAlign = "center";\n        ctx.textBaseline = "middle";\n        ctx.fillText("💰", loot.x, loot.y);\n      });\n\n      // Draw Police Cars\n      cops.forEach(cop => {\n        ctx.save();\n        ctx.translate(cop.x, cop.y);\n\n        // Police Siren Light\n        const sirenColor = Math.sin(cop.sirenFlash) > 0 ? \'#ef4444\' : \'#3b82f6\';\n        ctx.fillStyle = sirenColor;\n        ctx.beginPath();\n        ctx.arc(0, -14, 6, 0, Math.PI * 2);\n        ctx.fill();\n\n        // Car Body\n        ctx.font = "28px sans-serif";\n        ctx.textAlign = "center";\n        ctx.textBaseline = "middle";\n        ctx.fillText("🚓", 0, 0);\n        ctx.restore();\n      });\n\n      // Draw Player (Robber)\n      ctx.save();\n      ctx.translate(player.x, player.y);\n      if (isBoosting) {\n        // Boost flame / smoke trail\n        ctx.font = "20px sans-serif";\n        ctx.fillText("💨", -18, 12);\n      }\n      ctx.font = "30px sans-serif";\n      ctx.textAlign = "center";\n      ctx.textBaseline = "middle";\n      ctx.fillText("🦹", 0, 0);\n      ctx.restore();\n    }\n\n    function loop() {\n      update();\n      render();\n      requestAnimationFrame(loop);\n    }\n    requestAnimationFrame(loop);\n  </script>\n</body>\n</html>\n'
